exercises.solution:
const PLACEHOLDER = '[tool result cleared]';

function clearOldToolResults(messages, keepLast = 3) {
  // เดินจากท้ายไปต้น เพื่อนับ tool_result ที่ใหม่ที่สุดก่อน
  let seen = 0;
  const out = [];
  for (let i = messages.length - 1; i >= 0; i--) {
    const m = messages[i];
    if (!Array.isArray(m.content)) {
      out.push(m);
      continue;
    }
    const blocks = [];
    for (let j = m.content.length - 1; j >= 0; j--) {
      const b = m.content[j];
      if (b.type === 'tool_result') {
        seen++;
        // เก็บ type และ tool_use_id ไว้ เพื่อให้คู่ tool_use / tool_result ยังครบ
        blocks.push(seen > keepLast ? { ...b, content: PLACEHOLDER } : b);
      } else {
        blocks.push(b);
      }
    }
    out.push({ ...m, content: blocks.reverse() });
  }
  return out.reverse();
}
